<?php
declare(strict_types=1);
final class KsSuite {
 public array $clients=[];public array $data=[];private int $serial=0;
 public function __construct(public PDO $db,public KsCases $t,public array $accounts,public string $base,public string $tag,public string $runDir){}
 public function c(string $role):KsHttp{if(!isset($this->clients[$role]))throw new RuntimeException('Login fixture belum lulus: '.$role);return $this->clients[$role];}
 public function ok(array $r,int $status=200):void{ksAssert($r['status']===$status,'HTTP '.$r['status'].'; harapan '.$status);ksAssert(!preg_match('/(?:Fatal error:|Warning:|Deprecated:|Uncaught .*Exception)/',$r['body']),'PHP mengeluarkan error pada respons');}
 public function test(string $title,callable $fn):mixed{return $this->t->check($title,$fn);}
 public function reg(string $suffix,string $role='admin1'):array {
  $id='UT-'.$this->tag.'-'.$suffix;$motor=ksMotorData($this->tag,$suffix);$data=ksCustomerData($id,'Uji '.$this->tag.' '.$suffix)+$motor+['mode'=>'baru'];
  $r=$this->c($role)->submit('panel/pendaftaran.php',['aksi'=>'daftar'],$data);$this->ok($r);
  ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM kepemilikan_motor WHERE no_polisi=? AND id_pelanggan=? AND tanggal_selesai IS NULL',[$motor['no_polisi'],$id])===1,'Pendaftaran tidak tersimpan atomik');return ['id'=>$id,'motor'=>$motor['no_polisi']];
 }
 public function wo(array $reg,string $role='admin1',string $mechanic='tech1',string $estimate='100000'):string {
  $marker='Uji '.$this->tag.' kasus '.(++$this->serial);$r=$this->c($role)->submit('panel/work_order.php?buat=1',['aksi'=>'buat'],['kode_cabang'=>$this->accounts[$role]['branch']??'CBG001','id_pelanggan'=>$reg['id'],'no_polisi'=>$reg['motor'],'id_mekanik_pj'=>$this->accounts[$mechanic]['staff'],'keluhan'=>$marker,'estimasi_biaya'=>$estimate]);$this->ok($r);
  $id=ksOne($this->db,'SELECT no_work_order FROM work_order WHERE keluhan=?',[$marker]);ksAssert(is_string($id)&&$id!=='','WO tidak tersimpan');return $id;
 }
 public function addService(string $wo,string $code,string $cost='75000',string $role='admin1'):array {
  return $this->c($role)->submit('panel/work_order.php?lihat='.rawurlencode($wo).'&bagian=jasa&tambah=1',['aksi'=>'r01b_jasa_tambah'],['kode_jasa'=>$code,'biaya'=>$cost]);
 }
 public function status(string $wo,string $from,string $to,string $role='tech1'):array {
  $page=$this->accounts[$role]['role']==='rl_service_tech'?'pekerjaan.php':'work_order.php';$client=$this->c($role);$r=$client->get('panel/'.$page.'?lihat='.rawurlencode($wo));
  try{$form=$client->form($r,['aksi'=>'r01d_status']);return $client->postForm($form,['status_awal'=>$from,'status_tujuan'=>$to]);}
  catch(RuntimeException $e){return $client->request('POST','panel/'.$page,['csrf'=>$client->csrf(),'aksi'=>'r01d_status','no_work_order'=>$wo,'status_awal'=>$from,'status_tujuan'=>$to]);}
 }
 public function finish(string $wo,string $role='tech1'):void{$this->ok($this->status($wo,'MENUNGGU','PROSES',$role));$this->ok($this->status($wo,'PROSES','SELESAI',$role));ksAssert(ksOne($this->db,'SELECT status_pekerjaan FROM work_order WHERE no_work_order=?',[$wo])==='SELESAI');}
 public function stockForm(string $code,string $role='stock1',string $branch='CBG001'):array{return $this->c($role)->form($this->c($role)->get('panel/stok.php?cabang_pilih='.$branch.'&barang_pilih='.rawurlencode($code)),['kode_suku_cadang'=>$code]);}
 public function stockWrite(string $code,string $action,string $qty,string $min='',string $role='stock1',string $branch='CBG001'):array{return $this->c($role)->postForm($this->stockForm($code,$role,$branch),['aksi'=>$action,'jumlah'=>$qty,'minimum'=>$min,'catatan'=>'Uji mutasi '.$this->tag]);}
 public function run():void {
  $this->loginAndAccess();$this->masters();$this->registrationAndOwnership();$this->inventory();$this->workOrders();$this->payments();$this->corporate();$this->auditTerpadu();$this->reportsAndDatabase();
 }
 private function loginAndAccess():void {
  $this->t->group='Login dan sesi';
  foreach($this->accounts as $role=>$a)$this->test('Login HTTP '.$role,function()use($role,$a){$h=new KsHttp($this->base,$role);$r=$h->login($a['username'],$a['password']);$this->ok($r);ksAssert(!str_ends_with(parse_url($r['url'],PHP_URL_PATH),'/login.php'),'Login tidak berpindah ke panel');ksAssert(str_contains($r['body'],$a['username']),'Identitas akun tidak ada di panel');$this->clients[$role]=$h;});
  $this->test('Password salah tidak membuka panel',function(){$h=new KsHttp($this->base,'login-negatif');$a=$this->accounts['owner'];$r=$h->login($a['username'],'SALAH-'.bin2hex(random_bytes(4)));$this->ok($r);ksAssert(str_contains($r['body'],'Username atau password salah'));$r=$h->get('panel/index.php',false);ksAssert($r['status']===303&&str_contains($r['location'],'login.php'));});
  $this->test('Login tanpa CSRF ditolak',function(){$h=new KsHttp($this->base,'csrf-login');$r=$h->request('POST','login.php',['username'=>$this->accounts['owner']['username'],'password'=>'salah']);$this->ok($r,403);});
  $this->test('Lima login gagal memblokir percobaan berikutnya',function(){$h=new KsHttp($this->base,'batas-login');$a=$this->accounts['owner'];for($i=0;$i<5;$i++)$h->login($a['username'],'salah');$r=$h->login($a['username'],$a['password']);$this->ok($r);ksAssert(str_contains($r['body'],'Terlalu banyak percobaan'));});
  $this->test('Logout GET dan POST tanpa CSRF ditolak',function(){$h=new KsHttp($this->base,'logout');$a=$this->accounts['owner'];$h->login($a['username'],$a['password']);$this->ok($h->get('logout.php',false),405);$this->ok($h->request('POST','logout.php',[],false),403);$this->ok($h->get('panel/index.php'));});
  $this->test('Logout POST sah mengakhiri sesi',function(){$h=new KsHttp($this->base,'logout-sah');$a=$this->accounts['owner'];$h->login($a['username'],$a['password']);$r=$h->request('POST','logout.php',['csrf'=>$h->csrf()]);$this->ok($r);ksAssert(str_ends_with(parse_url($r['url'],PHP_URL_PATH),'/login.php'));});
  $allow=[
   'owner'=>['pelanggan.php','motor.php','jasa.php','suku_cadang.php','supplier.php','work_order.php','pembayaran.php','tagihan_korporat.php','stok.php','laporan.php','pendaftaran.php','katalog.php','audit.php','panduan.php'],
   'admin1'=>['work_order.php','laporan.php','pendaftaran.php','katalog.php','panduan.php'],
   'cash1'=>['pembayaran.php','tagihan_korporat.php','laporan.php','katalog.php','panduan.php'],
   'stock1'=>['stok.php','laporan.php','katalog.php','panduan.php'],'tech1'=>['pekerjaan.php','panduan.php'],'audit'=>['laporan.php','audit.php','panduan.php']];
  $pages=['pelanggan.php','motor.php','jasa.php','suku_cadang.php','supplier.php','work_order.php','pembayaran.php','tagihan_korporat.php','stok.php','laporan.php','pendaftaran.php','katalog.php','audit.php','pekerjaan.php','panduan.php'];
  $this->t->group='RBAC enam role melalui HTTP';
  foreach($allow as $role=>$list)foreach($pages as $page)$this->test($role.' GET '.$page,function()use($role,$list,$page){$this->ok($this->c($role)->get('panel/'.$page),in_array($page,$list,true)?200:403);});
  foreach($allow as $role=>$list)foreach(['pelanggan.php','motor.php','jasa.php','suku_cadang.php','supplier.php','work_order.php','pembayaran.php','stok.php'] as $page){if(in_array($page,$list,true))continue;$this->test($role.' POST terlarang '.$page,function()use($role,$page){$r=$this->c($role)->request('POST','panel/'.$page,['csrf'=>$this->c($role)->csrf(),'aksi'=>'tambah']);$this->ok($r,403);});}
  foreach(['cash1'=>'pembayaran.php','stock1'=>'stok.php','tech1'=>'pekerjaan.php','audit'=>'laporan.php'] as $role=>$dest)$this->test('Halaman awal '.$role,function()use($role,$dest){$r=$this->c($role)->get('panel/index.php');$this->ok($r);ksAssert(str_ends_with(parse_url($r['url'],PHP_URL_PATH),'/'.$dest));});
 }
 private function masters():void {
  $this->t->group='CRUD master Owner';$owner=$this->c('owner');
  foreach([
   ['jasa','jasa.php','jasa_servis','kode_jasa','uraian_jasa_servis'],['part','suku_cadang.php','suku_cadang','kode_suku_cadang','nama_suku_cadang'],['supplier','supplier.php','supplier','id_supplier','nama_supplier']
  ] as [$key,$page,$table,$pk,$col]){
   $name='Uji '.$this->tag.' '.$key;
   $code=$this->test('Tambah '.$key,function()use($owner,$page,$table,$pk,$col,$name){$this->ok($owner->submit('panel/'.$page,['aksi'=>'tambah'],[$col=>$name]));$code=ksOne($this->db,'SELECT '.ksName($pk).' FROM '.ksName($table).' WHERE '.ksName($col).'=?',[$name]);ksAssert(is_string($code));return $code;});
   if(!$code){$this->t->blocked('Lanjutan '.$key,'Tambah master belum lulus');continue;}$this->data[$key]=$code;
   $this->test('Baca dan cari '.$key,function()use($owner,$page,$name){$r=$owner->get('panel/'.$page.'?q='.rawurlencode($name));$this->ok($r);ksAssert(str_contains($r['body'],$name));});
   $this->test('Ubah '.$key,function()use($owner,$page,$code,$table,$pk,$col,$name){$this->ok($owner->submit('panel/'.$page.'?ubah='.rawurlencode($code),['aksi'=>'ubah'],[$pk=>$code,$col=>$name.' revisi']));ksAssert(ksOne($this->db,'SELECT '.ksName($col).' FROM '.ksName($table).' WHERE '.ksName($pk).'=?',[$code])===$name.' revisi');});
   $this->test('Nama duplikat '.$key.' ditolak',function()use($owner,$page,$table,$col,$name){$owner->submit('panel/'.$page,['aksi'=>'tambah'],[$col=>$name.' revisi']);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM '.ksName($table).' WHERE '.ksName($col).'=?',[$name.' revisi'])===1);});
   $this->test('Nama kosong '.$key.' ditolak',function()use($owner,$page,$table,$col){$before=(int)ksOne($this->db,'SELECT COUNT(*) FROM '.ksName($table));$owner->submit('panel/'.$page,['aksi'=>'tambah'],[$col=>'']);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM '.ksName($table))===$before);});
   $this->test('CSRF kosong '.$key.' ditolak',function()use($owner,$page,$col){$f=$owner->form($owner->get('panel/'.$page),['aksi'=>'tambah']);$this->ok($owner->postForm($f,['csrf'=>'',$col=>'Uji tanpa csrf']),403);});
   $this->test('Hapus '.$key.' yang tidak direferensikan',function()use($owner,$page,$table,$pk,$col,$name){$owner->submit('panel/'.$page,['aksi'=>'tambah'],[$col=>$name.' hapus']);$temp=ksOne($this->db,'SELECT '.ksName($pk).' FROM '.ksName($table).' WHERE '.ksName($col).'=?',[$name.' hapus']);ksAssert(is_string($temp));$this->ok($owner->submit('panel/'.$page.'?q='.rawurlencode($name.' hapus'),['aksi'=>'hapus',$pk=>$temp]));ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM '.ksName($table).' WHERE '.ksName($pk).'=?',[$temp])===0);});
  }
  if(isset($this->data['part'],$this->data['supplier'])){
   $s=$this->data['supplier'];$p=$this->data['part'];
   $this->test('Hubungkan supplier dengan barang',function()use($owner,$s,$p){$this->ok($owner->submit('panel/supplier.php?pilih='.$s,['aksi'=>'simpan_barang'],['barang'=>[$p]]));ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM supplier_suku_cadang WHERE id_supplier=? AND kode_suku_cadang=?',[$s,$p])===1);});
   $this->test('Supplier yang memasok barang tidak dapat dihapus',function()use($owner,$s){$owner->submit('panel/supplier.php?q='.rawurlencode('Uji '.$this->tag.' supplier revisi'),['aksi'=>'hapus','id_supplier'=>$s]);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM supplier WHERE id_supplier=?',[$s])===1);});
   $this->test('Lepas lalu pasang kembali hubungan supplier',function()use($owner,$s,$p){$this->ok($owner->submit('panel/supplier.php?pilih='.$s,['aksi'=>'simpan_barang'],['barang'=>[]]));ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM supplier_suku_cadang WHERE id_supplier=?',[$s])===0);$this->ok($owner->submit('panel/supplier.php?pilih='.$s,['aksi'=>'simpan_barang'],['barang'=>[$p]]));});
  }
 }
 private function registrationAndOwnership():void {
  $this->t->group='Pelanggan, motor dan kepemilikan';$owner=$this->c('owner');
  $reg=$this->test('Admin mendaftarkan pelanggan dan motor atomik',fn()=>$this->reg('A'));if(!$reg){$this->t->blocked('WO dan pembayaran','Pendaftaran dasar belum lulus');return;}$this->data['reg']=$reg;
  $this->data['reg2']=$this->test('Admin cabang kedua mendaftarkan motor',fn()=>$this->reg('B','admin2'));
  $this->test('Pendaftaran tidak menguasai cabang favorit global',function()use($reg){ksAssert(ksOne($this->db,'SELECT kode_cabang_favorit FROM pelanggan WHERE id_pelanggan=?',[$reg['id']])==='CBG001');});
  $this->test('Motor duplikat membatalkan pelanggan baru',function()use($reg){$id='UT-'.$this->tag.'-D';$payload=ksCustomerData($id,'Uji duplikat '.$this->tag)+ksMotorData($this->tag,'A')+['mode'=>'baru'];$this->c('admin1')->submit('panel/pendaftaran.php',['aksi'=>'daftar'],$payload);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM pelanggan WHERE id_pelanggan=?',[$id])===0);});
  $this->test('Motor baru untuk pelanggan terdaftar',function()use($reg){$m=ksMotorData($this->tag,'C');$this->ok($this->c('admin1')->submit('panel/pendaftaran.php?mode=terdaftar',['aksi'=>'daftar'],['mode'=>'terdaftar','id_pelanggan'=>$reg['id']]+$m));ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM kepemilikan_motor WHERE no_polisi=? AND id_pelanggan=? AND tanggal_selesai IS NULL',[$m['no_polisi'],$reg['id']])===1);});
  $id='UT-'.$this->tag.'-P';$payload=ksCustomerData($id,'Uji pelanggan '.$this->tag);
  $this->test('Owner tambah pelanggan',function()use($owner,$id,$payload){$this->ok($owner->submit('panel/pelanggan.php',['aksi'=>'tambah'],$payload));ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM pelanggan WHERE id_pelanggan=?',[$id])===1);});
  $this->test('Owner ubah pelanggan',function()use($owner,$id,$payload){$v=$payload;$v['nama_pelanggan'].=' revisi';$this->ok($owner->submit('panel/pelanggan.php?ubah='.$id,['aksi'=>'ubah'],$v));ksAssert(ksOne($this->db,'SELECT nama_pelanggan FROM pelanggan WHERE id_pelanggan=?',[$id])===$v['nama_pelanggan']);});
  $this->test('Nomor identitas duplikat ditolak',function()use($owner,$payload){$v=$payload;$v['id_pelanggan']='UT-'.$this->tag.'-Q';$owner->submit('panel/pelanggan.php',['aksi'=>'tambah'],$v);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM pelanggan WHERE id_pelanggan=?',[$v['id_pelanggan']])===0);});
  $m=ksMotorData($this->tag,'D');
  $this->test('Owner tambah motor',function()use($owner,$m){$this->ok($owner->submit('panel/motor.php',['aksi'=>'tambah'],$m));ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM motor WHERE no_polisi=?',[$m['no_polisi']])===1);});
  $this->test('Owner ubah motor',function()use($owner,$m){$v=$m;$v['warna']='Biru';$this->ok($owner->submit('panel/motor.php?ubah='.rawurlencode($m['no_polisi']),['aksi'=>'ubah'],$v+['no_polisi_asli'=>$m['no_polisi']]));ksAssert(ksOne($this->db,'SELECT warna FROM motor WHERE no_polisi=?',[$m['no_polisi']])==='Biru');});
  $this->test('Rangka atau mesin duplikat ditolak',function()use($owner,$m){$v=$m;$v['no_polisi']='UT '.$this->tag.' E';$owner->submit('panel/motor.php',['aksi'=>'tambah'],$v);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM motor WHERE no_polisi=?',[$v['no_polisi']])===0);});
  $this->test('Pemilik aktif dan histori perpindahan',function()use($owner,$m,$id,$reg){$today=(string)ksOne($this->db,'SELECT CURDATE()');$d1=(new DateTimeImmutable($today))->modify('-2 days')->format('Y-m-d');$d2=(new DateTimeImmutable($today))->modify('-1 day')->format('Y-m-d');
   $this->ok($owner->submit('panel/motor.php?pilih='.rawurlencode($m['no_polisi']),['aksi'=>'tetapkan_pemilik'],['id_pelanggan'=>$id,'tanggal_mulai'=>$d1]));
   $this->ok($owner->submit('panel/motor.php?pilih='.rawurlencode($m['no_polisi']),['aksi'=>'tetapkan_pemilik'],['id_pelanggan'=>$reg['id'],'tanggal_mulai'=>$d2]));
   ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM kepemilikan_motor WHERE no_polisi=?',[$m['no_polisi']])===2);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM kepemilikan_motor WHERE no_polisi=? AND tanggal_selesai IS NULL',[$m['no_polisi']])===1);
  });
  $this->test('Motor yang punya histori tidak dapat dihapus',function()use($owner,$m){$owner->request('POST','panel/motor.php',['csrf'=>$owner->csrf(),'aksi'=>'hapus','no_polisi'=>$m['no_polisi']]);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM motor WHERE no_polisi=?',[$m['no_polisi']])===1);});
  $this->test('Owner hapus pelanggan tanpa relasi',function()use($owner,$payload){$v=$payload;$v['id_pelanggan']='UT-'.$this->tag.'-Z';$v['no_identitas']='ID-'.$v['id_pelanggan'];$owner->submit('panel/pelanggan.php',['aksi'=>'tambah'],$v);$this->ok($owner->submit('panel/pelanggan.php?q='.rawurlencode($v['id_pelanggan']),['aksi'=>'hapus','id_pelanggan'=>$v['id_pelanggan']]));ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM pelanggan WHERE id_pelanggan=?',[$v['id_pelanggan']])===0);});
  $this->test('Owner hapus motor tanpa relasi',function()use($owner){$v=ksMotorData($this->tag,'Z');$owner->submit('panel/motor.php',['aksi'=>'tambah'],$v);$this->ok($owner->submit('panel/motor.php?q='.rawurlencode($v['no_polisi']),['aksi'=>'hapus','no_polisi'=>$v['no_polisi']]));ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM motor WHERE no_polisi=?',[$v['no_polisi']])===0);});
 }
 private function inventory():void {
  $this->t->group='Gudang dan persediaan';$code=$this->data['part']??null;if(!$code){$this->t->blocked('Mutasi stok','Master suku cadang belum lulus');return;}
  foreach([['awal','20','5',20,5],['masuk','3','',23,5],['koreksi','18','',18,5],['minimum','','6',18,6]] as [$action,$qty,$min,$stock,$limit])$this->test('Mutasi '.$action,function()use($code,$action,$qty,$min,$stock,$limit){$this->ok($this->stockWrite($code,$action,$qty,$min));ksAssert((int)ksOne($this->db,'SELECT jumlah_stok FROM stok_cabang WHERE kode_cabang=\'CBG001\' AND kode_suku_cadang=?',[$code])===$stock);ksAssert((int)ksOne($this->db,'SELECT stok_minimum FROM stok_cabang WHERE kode_cabang=\'CBG001\' AND kode_suku_cadang=?',[$code])===$limit);});
  $this->test('Riwayat mutasi menyimpan pencatat',function()use($code){ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM mutasi_stok_manual WHERE kode_suku_cadang=? AND id_akun=?',[$code,$this->accounts['stock1']['id']])===4);});
  $this->test('Replay mutasi tidak menambah stok dua kali',function()use($code){$f=$this->stockForm($code);$this->ok($this->c('stock1')->postForm($f,['aksi'=>'masuk','jumlah'=>'1','minimum'=>'','catatan'=>'Uji replay stok']));$before=ksTableDigest($this->db,'stok_cabang');$this->c('stock1')->postForm($f,['aksi'=>'masuk','jumlah'=>'1','minimum'=>'','catatan'=>'Uji replay stok']);ksAssert(ksTableDigest($this->db,'stok_cabang')===$before);});
  $this->test('Jumlah negatif ditolak',function()use($code){$before=ksTableDigest($this->db,'stok_cabang');$this->stockWrite($code,'masuk','-1');ksAssert(ksTableDigest($this->db,'stok_cabang')===$before);});
  $this->test('Snapshot stok kedaluwarsa tidak menimpa perubahan baru',function()use($code){$f=$this->stockForm($code);ksExec($this->db,"UPDATE stok_cabang SET jumlah_stok=jumlah_stok+1 WHERE kode_cabang='CBG001' AND kode_suku_cadang=?",[$code]);$before=ksTableDigest($this->db,'stok_cabang');$this->c('stock1')->postForm($f,['aksi'=>'koreksi','jumlah'=>'99','minimum'=>'','catatan'=>'Uji konflik snapshot']);ksAssert(ksTableDigest($this->db,'stok_cabang')===$before);});
  $this->test('Gudang menolak GET cabang lain',function()use($code){$this->ok($this->c('stock2')->get('panel/stok.php?cabang_pilih=CBG001&barang_pilih='.$code),404);});
  $this->test('Gudang menolak POST cabang lain',function()use($code){$before=ksTableDigest($this->db,'stok_cabang');$this->ok($this->c('stock2')->request('POST','panel/stok.php',['csrf'=>$this->c('stock2')->csrf(),'kode_cabang'=>'CBG001','kode_suku_cadang'=>$code,'aksi'=>'masuk','jumlah'=>'1']),403);ksAssert(ksTableDigest($this->db,'stok_cabang')===$before);});
  $this->test('Gudang tanpa CSRF ditolak',function()use($code){$this->ok($this->c('stock1')->postForm($this->stockForm($code),['csrf'=>'','aksi'=>'masuk','jumlah'=>'1']),403);});
  $this->test('Katalog menampilkan stok dan supplier',function()use($code){$r=$this->c('stock1')->get('panel/katalog.php?q='.rawurlencode($code));$this->ok($r);ksAssert((bool)preg_match('~<td>\s*'.preg_quote(htmlspecialchars($code,ENT_QUOTES,'UTF-8'),'~').'\s*·~u',$r['body'])&&str_contains($r['body'],'Daftar supplier'),'Barang fixture tidak muncul dalam sel tabel katalog atau daftar supplier tidak tersedia.');});
 }
 private function workOrders():void {
  $this->t->group='Work Order, jasa, barang dan mekanik';$reg=$this->data['reg']??null;$j=$this->data['jasa']??null;$part=$this->data['part']??null;
  if(!$reg||!$j||!$part){$this->t->blocked('Alur WO','Pendaftaran/master prasyarat belum lulus');return;}
  $this->test('WO tanpa motor ditolak',function()use($reg){$before=(int)ksOne($this->db,'SELECT COUNT(*) FROM work_order');$this->c('admin1')->submit('panel/work_order.php?buat=1',['aksi'=>'buat'],['kode_cabang'=>'CBG001','id_pelanggan'=>$reg['id'],'no_polisi'=>'','id_mekanik_pj'=>$this->accounts['tech1']['staff'],'keluhan'=>'Uji motor kosong tidak sah','estimasi_biaya'=>'0']);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM work_order')===$before);});
  $wo=$this->test('Admin membuat WO cabangnya',fn()=>$this->wo($reg));if(!$wo)return;$this->data['wo']=$wo;
