 private function payments():void {
  $this->t->group='Pembayaran individual dan bukti';$reg=$this->data['reg']??null;$j=$this->data['jasa']??null;if(!$reg||!$j){$this->t->blocked('Pembayaran','Data WO prasyarat belum lulus');return;}
  $cash=$this->c('cash1');
  if(isset($this->data['wo'])){
   $wo=$this->data['wo'];$this->test('Rincian kasir memuat kode item harga qty dan metode',function()use($cash,$wo,$j){$r=$cash->get('panel/pembayaran.php?lihat='.$wo);$this->ok($r);ksAssert(str_contains($r['body'],$j)&&str_contains($r['body'],'Harga satuan')&&str_contains($r['body'],'Metode pembayaran'));});
   $this->test('Kasir cabang lain tidak membaca rincian',function()use($wo){$this->ok($this->c('cash2')->get('panel/pembayaran.php?lihat='.$wo),404);});
  }
  $pending=$this->test('Buat WO belum selesai untuk uji penolakan',fn()=>$this->wo($reg));
  if($pending){$this->addService($pending,$j,'25000');$this->test('WO belum selesai tidak menampilkan form pelunasan',function()use($cash,$pending){$r=$cash->get('panel/pembayaran.php?lihat='.$pending);$this->ok($r);ksAssert(!str_contains($r['body'],'name="token_bayar"'));$r=$cash->request('POST','panel/pembayaran.php',['csrf'=>$cash->csrf(),'aksi'=>'lunasi','no_work_order'=>$pending,'token_bayar'=>str_repeat('a',48),'diskon_member'=>'0','metode_pembayaran'=>'TUNAI']);ksAssert(in_array($r['status'],[403,409],true));ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM pembayaran WHERE no_work_order=?',[$pending])===0);});}
  foreach(['TUNAI','TRANSFER','QRIS','KARTU_DEBIT'] as $method)$this->test('Pelunasan '.$method.' presisi dan tidak ganda',function()use($reg,$j,$cash,$method){$wo=$this->wo($reg);$this->ok($this->addService($wo,$j,'25000'));$this->finish($wo);$form=$cash->form($cash->get('panel/pembayaran.php?lihat='.$wo),['aksi'=>'lunasi']);
   $this->ok($cash->postForm($form,['diskon_member'=>'500','metode_pembayaran'=>$method]));ksAssert(ksOne($this->db,'SELECT total_bayar FROM pembayaran WHERE no_work_order=?',[$wo])==='24500.00');ksAssert(ksOne($this->db,'SELECT metode_pembayaran FROM pembayaran WHERE no_work_order=?',[$wo])===$method);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM penerimaan_kas WHERE no_work_order=?',[$wo])===1);
   $r=$cash->postForm($form,['diskon_member'=>'500','metode_pembayaran'=>$method]);$this->ok($r,409);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM penerimaan_kas WHERE no_work_order=?',[$wo])===1);
   $r=$cash->get('panel/pembayaran.php?lihat='.$wo);ksAssert(str_contains($r['body'],'Cetak bukti pembayaran')&&str_contains($r['body'],'Lunas'));$this->data['paid']=$wo;
  });
  $this->test('POST pembayaran cabang lain ditolak tanpa mutasi',function()use($reg,$j,$cash){$wo=$this->wo($reg);$this->addService($wo,$j,'10000');$this->finish($wo);$f=$cash->form($cash->get('panel/pembayaran.php?lihat='.$wo),['aksi'=>'lunasi']);$f['fields']['csrf']=$this->c('cash2')->csrf();$this->ok($this->c('cash2')->postForm($f,['diskon_member'=>'0','metode_pembayaran'=>'TUNAI']),403);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM pembayaran WHERE no_work_order=?',[$wo])===0);});
  $this->test('Diskon berlebih dan CSRF kosong tidak menyimpan uang',function()use($reg,$j,$cash){$wo=$this->wo($reg);$this->addService($wo,$j,'10000');$this->finish($wo);$f=$cash->form($cash->get('panel/pembayaran.php?lihat='.$wo),['aksi'=>'lunasi']);$this->ok($cash->postForm($f,['diskon_member'=>'10001','metode_pembayaran'=>'TUNAI']),409);$this->ok($cash->postForm($f,['csrf'=>'','diskon_member'=>'0','metode_pembayaran'=>'TUNAI']),403);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM pembayaran WHERE no_work_order=?',[$wo])===0);});
  $this->test('Snapshot biaya berubah menolak pembayaran lama',function()use($reg,$j,$cash){$wo=$this->wo($reg);$this->addService($wo,$j,'10000');$this->finish($wo);$f=$cash->form($cash->get('panel/pembayaran.php?lihat='.$wo),['aksi'=>'lunasi']);ksExec($this->db,'UPDATE detail_wo_jasa SET biaya=11000 WHERE no_work_order=? AND kode_jasa=?',[$wo,$j]);$this->ok($cash->postForm($f,['diskon_member'=>'0','metode_pembayaran'=>'TUNAI']),409);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM pembayaran WHERE no_work_order=?',[$wo])===0);});
 }
 private function corporate():void {
  $this->t->group='Korporat, kontrak, plafon dan tagihan';$owner=$this->c('owner');$j=$this->data['jasa']??null;if(!$j){$this->t->blocked('Korporat','Jasa prasyarat belum tersedia');return;}
  $today=(string)ksOne($this->db,'SELECT CURDATE()');$month=(new DateTimeImmutable($today))->modify('first day of last month')->format('Y-m');$start=$month.'-01';$end=(new DateTimeImmutable($today))->modify('last day of this month')->format('Y-m-d');
  $companies=[];
  foreach(['S','M'] as $suffix){$id='UC-'.$this->tag.'-'.$suffix;$payload=ksCustomerData($id,'Uji Korporat '.$this->tag.' '.$suffix);$payload['jenis_identitas']='NIB';$payload['nama_pic']='PIC Uji';
   $valid=$this->test('Daftar perusahaan '.$suffix,function()use($owner,$payload,$id){$this->ok($owner->submit('panel/pelanggan.php?tipe=korporat',['aksi'=>'tambah'],$payload));ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM pelanggan_korporat WHERE id_pelanggan=?',[$id])===1);return true;});if(!$valid)continue;
   $this->test('Tambah kontrak '.$suffix,function()use($owner,$id,$start,$end){$this->ok($owner->submit('panel/kontrak_korporat.php?id='.$id,['@field'=>'plafon_kredit'],['berlaku_mulai'=>$start,'berlaku_sampai'=>$end,'plafon_kredit'=>'100000']));ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM kontrak_korporat WHERE id_pelanggan=?',[$id])===1);});
   $this->test('Kontrak tumpang tindih '.$suffix.' ditolak',function()use($owner,$id,$start,$end){$this->ok($owner->submit('panel/kontrak_korporat.php?id='.$id,['@field'=>'plafon_kredit'],['berlaku_mulai'=>$start,'berlaku_sampai'=>$end,'plafon_kredit'=>'100000']),422);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM kontrak_korporat WHERE id_pelanggan=?',[$id])===1);});
   $m=ksMotorData($this->tag,$suffix);$this->test('Motor perusahaan '.$suffix,function()use($owner,$id,$m,$start){$this->ok($owner->submit('panel/motor.php',['aksi'=>'tambah'],$m));$this->ok($owner->submit('panel/motor.php?pilih='.rawurlencode($m['no_polisi']),['aksi'=>'tetapkan_pemilik'],['id_pelanggan'=>$id,'tanggal_mulai'=>$start]));});
   $companies[$suffix]=['id'=>$id,'motor'=>$m['no_polisi']];
  }
  if(isset($companies['S'])){
   $reg=$companies['S'];
   $this->test('Plafon menolak estimasi yang melebihi kredit',function()use($reg){$before=(int)ksOne($this->db,'SELECT COUNT(*) FROM work_order WHERE id_pelanggan=?',[$reg['id']]);try{$this->wo($reg,'admin1','tech1','100001');}catch(Throwable $e){}ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM work_order WHERE id_pelanggan=?',[$reg['id']])===$before);});
   $this->test('WO korporat terkait kontrak dan kena batas kumulatif',function()use($reg,$j){$wo=$this->wo($reg,'admin1','tech1','60000');$this->ok($this->addService($wo,$j,'60000'));ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM work_order_korporat WHERE no_work_order=?',[$wo])===1);$before=(int)ksOne($this->db,'SELECT COUNT(*) FROM work_order WHERE id_pelanggan=?',[$reg['id']]);try{$this->wo($reg,'admin2','tech2','50000');}catch(Throwable $e){}ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM work_order WHERE id_pelanggan=?',[$reg['id']])===$before);$this->data['corp_current']=$wo;});
  }
  foreach($companies as $kind=>$reg){$invoice=$this->test('Terbitkan tagihan '.($kind==='S'?'satu cabang':'campuran'),function()use($kind,$reg,$j,$month,$start,$owner){
    $contract=ksOne($this->db,'SELECT id_kontrak FROM kontrak_korporat WHERE id_pelanggan=?',[$reg['id']]);$branches=$kind==='S'?['CBG001']:['CBG001','CBG002'];
    foreach($branches as $i=>$branch){$wo='UT-'.$this->tag.'-'.$kind.$i;ksExec($this->db,"INSERT INTO work_order(no_work_order,tanggal_masuk,tanggal_selesai,kode_cabang,id_pelanggan,no_polisi,id_mekanik_pj,keluhan,estimasi_biaya,status_pekerjaan) VALUES (?,?,?,?,?,?,?,'Fixture historis tagihan bulanan',0,'SELESAI')",[$wo,$start.' 09:00:00',$start.' 10:00:00',$branch,$reg['id'],$reg['motor'],$this->accounts[$branch==='CBG001'?'tech1':'tech2']['staff']]);ksExec($this->db,'INSERT INTO work_order_korporat(no_work_order,id_pelanggan,id_kontrak) VALUES (?,?,?)',[$wo,$reg['id'],$contract]);ksExec($this->db,'INSERT INTO detail_wo_jasa(no_work_order,kode_jasa,biaya) VALUES (?,?,10000)',[$wo,$j]);}
    $this->ok($owner->submit('panel/tagihan_korporat.php?id='.$reg['id'].'&bulan='.$month,['aksi'=>'terbitkan']));$id=ksOne($this->db,'SELECT id_tagihan FROM tagihan_korporat WHERE id_pelanggan=? AND periode=?',[$reg['id'],$start]);ksAssert($id!==false);return (string)$id;
   });if(!$invoice)continue;$this->data['invoice_'.$kind]=$invoice;
   if($kind==='M'){$this->test('Kasir tidak membuka tagihan lintas cabang',function()use($invoice){$this->ok($this->c('cash1')->get('panel/tagihan_korporat.php?lihat='.$invoice),404);});}
   $payer=$kind==='S'?$this->c('cash1'):$owner;
   $this->test('Pelunasan '.($kind==='S'?'kasir cabang':'Owner lintas cabang').' dan replay ditolak',function()use($payer,$invoice){$f=$payer->form($payer->get('panel/tagihan_korporat.php?lihat='.$invoice),['aksi'=>'lunasi']);$this->ok($payer->postForm($f,['metode_pembayaran'=>'TRANSFER']));ksAssert(ksOne($this->db,'SELECT status_pembayaran FROM tagihan_korporat WHERE id_tagihan=?',[$invoice])==='LUNAS');ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM penerimaan_kas WHERE id_tagihan=?',[$invoice])===1);$r=$payer->postForm($f,['metode_pembayaran'=>'TRANSFER']);$this->ok($r,409);ksAssert((int)ksOne($this->db,'SELECT COUNT(*) FROM penerimaan_kas WHERE id_tagihan=?',[$invoice])===1);});
  }
  foreach(['admin1','cash1','stock1','tech1','audit'] as $role)$this->test('Kontrak tidak dapat dikelola '.$role,function()use($role,$companies){$reg=reset($companies);$this->ok($this->c($role)->get('panel/kontrak_korporat.php?id='.($reg['id']??'tidakada')),403);});
 }
 private function auditTerpadu():void {
 $this->t->group='Audit terpadu Tugas 4';
 $this->test('View satu baris untuk setiap WO',function(){ksAssert(ksOne($this->db,'SELECT COUNT(*) FROM vw_ringkasan_transaksi_terpadu')===ksOne($this->db,'SELECT COUNT(*) FROM work_order'));ksAssert((int)ksOne($this->db,'SELECT COUNT(*)-COUNT(DISTINCT no_work_order) FROM vw_ringkasan_transaksi_terpadu')===0);});
 $this->test('View tidak dapat diperbarui langsung',function(){ksAssert(ksOne($this->db,"SELECT IS_UPDATABLE FROM information_schema.VIEWS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='vw_ringkasan_transaksi_terpadu'")==='NO');});
 foreach(['S'=>1,'M'=>2] as $kind=>$count){if(!isset($this->data['invoice_'.$kind])){$this->t->blocked('Audit invoice '.$kind,'Penerbitan tagihan belum lulus');continue;}$invoice=$this->data['invoice_'.$kind];
 $this->test('Status dan metode korporat '.$kind,function()use($invoice,$count){$q=$this->db->prepare('SELECT * FROM vw_ringkasan_transaksi_terpadu WHERE id_tagihan=?');$q->execute([$invoice]);$rows=$q->fetchAll();ksAssert(count($rows)===$count);foreach($rows as $r)ksAssert($r['jenis_transaksi']==='KORPORAT'&&$r['status_pembayaran']==='LUNAS'&&$r['metode_pembayaran']==='TRANSFER'&&$r['waktu_penerimaan']!==null);});
 $this->test('Nilai invoice '.$kind.' tidak digandakan',function()use($invoice,$count){$sum=ksOne($this->db,'SELECT SUM(penerimaan_wo) FROM vw_ringkasan_transaksi_terpadu WHERE id_tagihan=?',[$invoice]);ksAssert($sum===ksOne($this->db,'SELECT SUM(nilai_final) FROM detail_tagihan_korporat WHERE id_tagihan=?',[$invoice])&&$sum===((string)(10000*$count)).'.00');});
 $wo='UT-'.$this->tag.'-'.$kind.'0';foreach(['owner','audit'] as $role)$this->test('Halaman audit '.$role.' menelusuri invoice '.$kind,function()use($wo,$invoice,$role){$r=$this->c($role)->get('panel/audit.php?q='.$wo);$this->ok($r);ksAssert(str_contains($r['body'],'Ringkasan pembayaran per WO')&&str_contains($r['body'],$wo)&&str_contains($r['body'],'Tagihan #'.$invoice)&&str_contains($r['body'],'TRANSFER'));});
 }
 if(isset($this->data['corp_current']))$this->test('WO korporat belum ditagihkan bukan penerimaan',function(){$q=$this->db->prepare('SELECT * FROM vw_ringkasan_transaksi_terpadu WHERE no_work_order=?');$q->execute([$this->data['corp_current']]);$r=$q->fetch();ksAssert($r['status_pembayaran']==='BELUM_DITAGIHKAN'&&$r['penerimaan_wo']==='0.00'&&$r['id_tagihan']===null);});
 if(isset($this->data['paid']))$this->test('Individual lunas memakai nilai bersih diskon',function(){$q=$this->db->prepare('SELECT * FROM vw_ringkasan_transaksi_terpadu WHERE no_work_order=?');$q->execute([$this->data['paid']]);$r=$q->fetch();ksAssert($r['jenis_transaksi']==='INDIVIDUAL'&&$r['status_pembayaran']==='LUNAS'&&$r['nilai_wo']==='24500.00'&&$r['penerimaan_wo']==='24500.00'&&$r['id_tagihan']===null);});
 $this->test('WO batal tidak ditagih',function(){ksAssert((int)ksOne($this->db,"SELECT COUNT(*) FROM vw_ringkasan_transaksi_terpadu WHERE status_pekerjaan='DIBATALKAN'")>0);ksAssert((int)ksOne($this->db,"SELECT COUNT(*) FROM vw_ringkasan_transaksi_terpadu WHERE status_pekerjaan='DIBATALKAN' AND (status_pembayaran<>'TIDAK_DITAGIH' OR penerimaan_wo<>0)")===0);});
 $this->test('Semua korporat lunas awal terbaca lunas',function(){ksAssert((int)ksOne($this->db,"SELECT COUNT(*) FROM vw_ringkasan_transaksi_terpadu v JOIN detail_tagihan_korporat d ON d.no_work_order=v.no_work_order JOIN tagihan_korporat t ON t.id_tagihan=d.id_tagihan WHERE t.status_pembayaran='LUNAS' AND v.status_pekerjaan<>'DIBATALKAN' AND v.status_pembayaran<>'LUNAS'")===0);});
 $this->test('View baseline Tugas 3 tetap tersedia',function(){ksAssert((int)ksOne($this->db,"SELECT COUNT(*) FROM information_schema.VIEWS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='vw_ringkasan_transaksi_audit'")===1);});
 }
 private function reportsAndDatabase():void {
  $this->t->group='Laporan, audit dan rincian';$today=(string)ksOne($this->db,'SELECT CURDATE()');$from=(new DateTimeImmutable($today))->modify('first day of last month')->format('Y-m-d');
  foreach(['owner','admin1','cash1','audit'] as $role)foreach(['riwayat','pendapatan','pemakaian','stok'] as $type)$this->test('Laporan '.$type.' oleh '.$role,function()use($role,$type,$today,$from){$r=$this->c($role)->get('panel/laporan.php?jenis='.$type.'&awal='.$from.'&akhir='.$today);$this->ok($r);ksAssert(str_contains($r['body'],'Cetak laporan'));});
  foreach(['pemakaian'=>200,'stok'=>200,'riwayat'=>403,'pendapatan'=>403] as $type=>$code)$this->test('Cakupan laporan Gudang '.$type,function()use($type,$code){$this->ok($this->c('stock1')->get('panel/laporan.php?jenis='.$type),$code);});
  $this->test('Rentang kosong mengembalikan hasil kosong',function(){$r=$this->c('audit')->get('panel/laporan.php?jenis=riwayat&awal=1900-01-01&akhir=1900-01-02');$this->ok($r);ksAssert(str_contains($r['body'],'Tidak ada data sesuai filter'));});
  $this->test('Rentang terbalik ditolak',function()use($today){$this->ok($this->c('audit')->get('panel/laporan.php?awal='.$today.'&akhir=1900-01-01'),422);});
  $this->test('Filter cabang lain tidak dapat dipakai Admin',function(){$this->ok($this->c('admin1')->get('panel/laporan.php?cabang=CBG002'),403);});
  if(isset($this->data['paid'])){$wo=$this->data['paid'];
   $this->test('Auditor membaca rincian item dan pembayaran',function()use($wo){$r=$this->c('audit')->get('panel/rincian_servis.php?wo='.$wo);$this->ok($r);ksAssert(str_contains($r['body'],'Harga satuan')&&str_contains($r['body'],'Garansi pekerjaan'));});
   $this->test('Auditor tidak menulis rincian atau audit',function()use($wo){$this->ok($this->c('audit')->request('POST','panel/rincian_servis.php?wo='.$wo,['csrf'=>$this->c('audit')->csrf()]),405);$this->ok($this->c('audit')->request('POST','panel/audit.php',['csrf'=>$this->c('audit')->csrf()]),405);});
   $this->test('Jejak audit dan penerimaan kas dapat dicari',function()use($wo){$r=$this->c('audit')->get('panel/audit.php?q='.$wo);$this->ok($r);ksAssert(str_contains($r['body'],$wo)&&str_contains($r['body'],$this->accounts['cash1']['username']));});
   $this->test('Pendapatan tidak berlipat akibat JOIN detail',function()use($today,$from){$expected=(string)ksOne($this->db,"SELECT COALESCE(SUM(p.total_bayar),0) FROM pembayaran p JOIN work_order w ON w.no_work_order=p.no_work_order JOIN penerimaan_kas k ON k.no_work_order=p.no_work_order WHERE w.kode_cabang='CBG001' AND p.status_pembayaran='LUNAS' AND k.dicatat_pada>=? AND k.dicatat_pada<DATE_ADD(?,INTERVAL 1 DAY) AND NOT EXISTS(SELECT 1 FROM work_order_korporat wk WHERE wk.no_work_order=w.no_work_order)",[$from,$today]);$r=$this->c('audit')->get('panel/laporan.php?jenis=pendapatan&cabang=CBG001&awal='.$from.'&akhir='.$today);$this->ok($r);ksAssert(str_contains($r['body'],'data-value="'.$expected.'"'),'Jumlah penerimaan individual pada laporan tidak sama dengan sumber pembayaran');});
  }
  if(isset($this->data['part']))$this->test('Stok minimum menampilkan barang yang kurang',function(){$part=$this->data['part'];ksExec($this->db,"UPDATE stok_cabang SET stok_minimum=jumlah_stok+1 WHERE kode_cabang='CBG001' AND kode_suku_cadang=?",[$part]);$r=$this->c('stock1')->get('panel/laporan.php?jenis=stok');$this->ok($r);ksAssert(str_contains($r['body'],$part));});
  $this->t->group='Objek SQL Tugas 2-3';
  if(isset($this->data['reg'],$this->data['jasa'])){
   $reg=$this->data['reg'];$j=$this->data['jasa'];
   $this->test('Trigger menolak tanggal masuk masa depan',function()use($reg){$denied=false;try{ksExec($this->db,"INSERT INTO work_order(no_work_order,tanggal_masuk,kode_cabang,id_pelanggan,no_polisi,id_mekanik_pj,keluhan) VALUES (?,DATE_ADD(NOW(),INTERVAL 1 DAY),'CBG001',?,?,?,'Uji tanggal masa depan')",['UT-'.$this->tag.'-F',$reg['id'],$reg['motor'],$this->accounts['tech1']['staff']]);}catch(PDOException $e){$denied=(int)($e->errorInfo[1]??0)===1644;}ksAssert($denied,'Tanggal masa depan tidak ditolak trigger');});
   foreach(['sp_riwayat_servis_motor'=>[$reg['motor']],'sp_daftar_wo_cabang'=>[$from,$today,'CBG001'],'sp_rincian_tagihan_wo'=>[$this->data['paid']??$this->data['wo']??'tidakada']] as $proc=>$args)$this->test('Stored procedure '.$proc,function()use($proc,$args){$s=$this->db->prepare('CALL '.ksName($proc).'('.implode(',',array_fill(0,count($args),'?')).')');$s->execute($args);$rows=$s->fetchAll();while($s->nextRowset())$s->fetchAll();$s->closeCursor();ksAssert(count($rows)>0,'Procedure tidak memberi hasil fixture');});
   $unpaid=$this->test('Buat fixture garansi belum lunas',function()use($reg,$j){$wo=$this->wo($reg);$this->ok($this->addService($wo,$j,'10000'));$this->finish($wo);ksExec($this->db,'INSERT INTO garansi(no_work_order,jumlah_hari_garansi,catatan_garansi) VALUES (?,30,?)',[$wo,'Garansi fixture uji']);return $wo;});
   if($unpaid){
    $this->test('Garansi SQL belum berlaku sebelum pembayaran lunas',function()use($unpaid){$value=ksOne($this->db,'SELECT fn_status_garansi_wo(?)',[$unpaid]);ksAssert($value==='BELUM BERLAKU','Fungsi SQL memberi '.$value.' untuk WO yang belum dibayar; syarat LUNAS belum diterapkan');});
    $this->test('Rincian UI garansi belum lunas menampilkan Belum berlaku',function()use($unpaid){$r=$this->c('audit')->get('panel/rincian_servis.php?wo='.$unpaid);$this->ok($r);ksAssert(str_contains($r['body'],'<strong>Belum berlaku</strong>'));});
   }
   if(isset($this->data['paid'])){$paid=$this->data['paid'];
    $this->test('Garansi lunas aktif dan tampil pada rincian',function()use($paid){ksExec($this->db,'INSERT INTO garansi(no_work_order,jumlah_hari_garansi,catatan_garansi) VALUES (?,30,?)',[$paid,'Garansi lunas fixture']);ksAssert(ksOne($this->db,'SELECT fn_status_garansi_wo(?)',[$paid])==='AKTIF');$r=$this->c('audit')->get('panel/rincian_servis.php?wo='.$paid);$this->ok($r);ksAssert(str_contains($r['body'],'<strong>Aktif</strong>'));});
    $this->test('Garansi kedaluwarsa sesuai tanggal selesai',function()use($paid){ksExec($this->db,'UPDATE work_order SET tanggal_masuk=DATE_SUB(NOW(),INTERVAL 41 DAY),tanggal_selesai=DATE_SUB(NOW(),INTERVAL 40 DAY) WHERE no_work_order=?',[$paid]);ksAssert(ksOne($this->db,'SELECT fn_status_garansi_wo(?)',[$paid])==='KEDALUWARSA');$r=$this->c('audit')->get('panel/rincian_servis.php?wo='.$paid);$this->ok($r);ksAssert(str_contains($r['body'],'<strong>Kedaluwarsa</strong>'));});
   }
   $this->test('WO tanpa garansi memberi status TIDAK ADA GARANSI',function(){ksAssert(ksOne($this->db,'SELECT fn_status_garansi_wo(?)',['UT-'.$this->tag.'-NONE'])==='TIDAK ADA GARANSI');});

  }
  $this->test('Ekspor SQL dan pemulihan tabel simulasi kehilangan data',function(){
   $name='uji_recovery_'.$this->tag;$this->db->exec('CREATE TABLE '.ksName($name).' (id INT PRIMARY KEY,catatan VARCHAR(50)) ENGINE=InnoDB');foreach([1,2,3] as $id)ksExec($this->db,'INSERT INTO '.ksName($name).' VALUES (?,?)',[$id,'Data uji '.$id]);$before=ksTableDigest($this->db,$name);
   $sql=ksCreateDefinition($this->db,'TABLE',$name).";\n";foreach($this->db->query('SELECT * FROM '.ksName($name).' ORDER BY id')->fetchAll() as $r)$sql.='INSERT INTO '.ksName($name).' VALUES ('.(int)$r['id'].','.$this->db->quote($r['catatan']).");\n";
   $path=$this->runDir.'/backup-simulasi-recovery.sql';ksAssert(file_put_contents($path,$sql)===strlen($sql),'Backup simulasi tidak tersimpan lengkap');ksExec($this->db,'DELETE FROM '.ksName($name).' WHERE id=2');ksAssert(ksTableDigest($this->db,$name)!==$before);$this->db->exec('DROP TABLE '.ksName($name));
   foreach(explode(';',file_get_contents($path)) as $statement)if(trim($statement)!=='')$this->db->exec($statement);
   ksAssert(ksTableDigest($this->db,$name)===$before,'Hash data setelah restore SQL tidak sama');
  });

 }
